package com.example.splitstory;
import android.app.*;import android.os.*;import android.webkit.*;import android.view.*;import android.widget.*;import android.graphics.Color;import android.content.*;import android.net.Uri;import java.io.*;import java.nio.charset.StandardCharsets;
public class MainActivity extends Activity {
WebView web;ValueCallback<Uri[]> files;volatile byte[] exportBytes;GameApkExporter apkExporter;long backTime;String exportName,latestExpected;
@Override public void onCreate(Bundle b){super.onCreate(b);apkExporter=new GameApkExporter(this);getWindow().setStatusBarColor(Color.rgb(16,23,33));getWindow().setNavigationBarColor(Color.rgb(16,23,33));LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.rgb(16,23,33));root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.consumeSystemWindowInsets();});web=new WebView(this);web.setBackgroundColor(Color.rgb(16,23,33));root.addView(web,new LinearLayout.LayoutParams(-1,-1));setContentView(root);root.requestApplyInsets();WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(true);settings.setMediaPlaybackRequiresUserGesture(false);settings.setAllowContentAccess(true);web.addJavascriptInterface(new Bridge(),"Android");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !r.getUrl().toString().startsWith("file:///android_asset/");}});web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(files!=null)files.onReceiveValue(null);files=cb;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);String[] types=p.getAcceptTypes();String type=types.length>0&&types[0].startsWith("image/")?"image/*":types.length>0&&types[0].startsWith("audio/")?"audio/*":types.length>0&&types[0].contains("package-archive")?"application/vnd.android.package-archive":"application/json";i.setType(type);try{startActivityForResult(i,1);}catch(Exception e){files.onReceiveValue(null);files=null;}return true;}@Override public boolean onJsConfirm(WebView v,String u,String m,JsResult r){new AlertDialog.Builder(MainActivity.this).setMessage(m).setPositiveButton("확인",(d,w)->r.confirm()).setNegativeButton("취소",(d,w)->r.cancel()).setOnCancelListener(d->r.cancel()).show();return true;}});web.loadUrl("file:///android_asset/index.html");if(Build.VERSION.SDK_INT>=33)ModernBack.register(this);}
class Bridge {
final PartitionStore content=new PartitionStore(getFilesDir());
@JavascriptInterface public String readChunk(String id){return content.readChunk(id);}
@JavascriptInterface public boolean saveChunks(String raw){return content.saveChunks(raw);}
@JavascriptInterface public boolean pruneChunks(String raw){return content.pruneChunks(raw);}
@JavascriptInterface public String creatorInfo(String id){try{return new CreatorSigning(MainActivity.this).info(id);}catch(Exception e){return "{\"error\":"+org.json.JSONObject.quote(e.getMessage())+"}";}}
@JavascriptInterface public String backupSigning(String id){try{return new CreatorSigning(MainActivity.this).backup(id);}catch(Exception e){return "{\"error\":"+org.json.JSONObject.quote(e.getMessage())+"}";}}
@JavascriptInterface public String restoreSigning(String id,String raw,int latest){try{boolean ok=new CreatorSigning(MainActivity.this).restore(id,raw,latest);return "{\"ok\":"+ok+"}";}catch(Exception e){return "{\"ok\":false,\"error\":"+org.json.JSONObject.quote(e.getMessage())+"}";}}
@JavascriptInterface public boolean markCreatorBackup(String id){try{CreatorKeys k=new CreatorSigning(MainActivity.this).get(id,false);if(k==null)return false;String pkg=ApkExportEngine.packageName(id,k.cert);return getSharedPreferences("creator-backups",0).edit().putBoolean(pkg,true).commit();}catch(Exception e){return false;}}
@JavascriptInterface public boolean chooseLatestApk(String expected){try{new org.json.JSONObject(expected);}catch(Exception e){return false;}runOnUiThread(()->{if(latestExpected!=null)return;latestExpected=expected;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/vnd.android.package-archive");try{startActivityForResult(i,4);}catch(Exception e){latestExpected=null;}});return true;}
@JavascriptInterface public boolean exportGameApk(String data,String gameId,String title){return apkExporter.start(data,gameId,title);}
@JavascriptInterface public boolean clearExportMedia(){return apkExporter.clearMedia();}
@JavascriptInterface public boolean stageExportMedia(String name,String base64){return apkExporter.stageMedia(name,base64);}
@JavascriptInterface public synchronized String readData(){File f=new File(getFilesDir(),"project.json");if(!f.exists())return "";try{return new String(java.nio.file.Files.readAllBytes(f.toPath()),StandardCharsets.UTF_8);}catch(Exception e){return "!READ_ERROR";}}
@JavascriptInterface public synchronized String readBackup(){try{return new String(java.nio.file.Files.readAllBytes(new File(getFilesDir(),"project.backup.json").toPath()),StandardCharsets.UTF_8);}catch(Exception e){return "";}}
@JavascriptInterface public synchronized boolean archiveCorrupt(){try{File f=new File(getFilesDir(),"project.json");if(f.exists())java.nio.file.Files.move(f.toPath(),new File(getFilesDir(),"project.corrupt."+System.currentTimeMillis()+".json").toPath());return true;}catch(Exception e){return false;}}
@JavascriptInterface public synchronized boolean saveData(String s){return content.saveIndex(s);}
@JavascriptInterface public void exportFile(String s,String name,String mime){if(s.length()>155000000){runOnUiThread(()->fileResult(false,"파일 크기 제한"));return;}runOnUiThread(()->{if(exportBytes!=null||apkExporter.busy.get()){fileResult(false,"먼저 파일 저장을 마쳐 주세요");return;}exportBytes=s.getBytes(StandardCharsets.UTF_8);exportName=name;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,name);try{startActivityForResult(i,2);}catch(Exception e){exportBytes=null;fileResult(false,"파일 선택기를 열지 못했습니다.");}});}
}
@Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==4){readLatestApk(result,data);return;}if(req==3){apkExporter.finish(result,data);return;}if(req==1&&files!=null){files.onReceiveValue(result==RESULT_OK&&data!=null?new Uri[]{data.getData()}:null);files=null;}if(req==2){byte[] bytes=exportBytes;exportBytes=null;if(result==RESULT_OK&&data!=null&&bytes!=null){new Thread(()->{boolean ok=false;try(OutputStream out=getContentResolver().openOutputStream(data.getData())){if(out==null)throw new IOException("저장 위치");out.write(bytes);out.flush();ok=true;}catch(Exception e){try{android.provider.DocumentsContract.deleteDocument(getContentResolver(),data.getData());}catch(Exception ignored){}}final boolean saved=ok;runOnUiThread(()->fileResult(saved,saved?"파일을 저장했습니다":"파일 저장 실패"));}).start();}else fileResult(false,"파일 저장을 취소했습니다.");}}
void fileResult(boolean ok,String message){web.evaluateJavascript("window.onFileExportResult && window.onFileExportResult("+ok+","+org.json.JSONObject.quote(message)+")",null);Toast.makeText(this,message,Toast.LENGTH_SHORT).show();}
void readLatestApk(int result,Intent data){String expected=latestExpected;latestExpected=null;if(result!=RESULT_OK||data==null||expected==null){latestResult(false,0,"APK 선택을 취소했습니다.");return;}new Thread(()->{File tmp=null;try{tmp=File.createTempFile("latest-game-",".apk",getCacheDir());try(InputStream in=getContentResolver().openInputStream(data.getData());OutputStream out=new FileOutputStream(tmp)){byte[] b=new byte[32768];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>150000000)throw new IOException("APK 크기 제한");out.write(b,0,n);}}com.android.apksig.ApkVerifier.Result signed=new com.android.apksig.ApkVerifier.Builder(tmp).setMinCheckedPlatformVersion(26).build().verify();if(!signed.isVerified())throw new IOException("APK 서명 확인 실패");org.json.JSONObject e=new org.json.JSONObject(expected);boolean match=false;for(java.security.cert.X509Certificate cert:signed.getSignerCertificates()){String fp=android.util.Base64.encodeToString(java.security.MessageDigest.getInstance("SHA-256").digest(cert.getEncoded()),android.util.Base64.NO_WRAP);if(fp.equals(e.getString("fingerprint")))match=true;}android.content.pm.PackageInfo info=getPackageManager().getPackageArchiveInfo(tmp.getAbsolutePath(),0);if(!match||info==null||!info.packageName.equals(e.getString("package")))throw new IOException("이 게임의 배포 APK가 아닙니다.");int version=info.versionCode;if(version<1||version==Integer.MAX_VALUE)throw new IOException("APK 버전 한도");latestResult(true,version,"최근 APK 버전 "+version+" 확인");}catch(Exception e){latestResult(false,0,e.getMessage());}finally{if(tmp!=null)tmp.delete();}},"LatestGameApk").start();}
void latestResult(boolean ok,int version,String message){runOnUiThread(()->web.evaluateJavascript("window.onLatestApkResult && window.onLatestApkResult("+ok+","+version+","+org.json.JSONObject.quote(message)+")",null));}

@Override public void onBackPressed(){handleBack();}
private void handleBack(){web.evaluateJavascript("window.appBack ? window.appBack() : 'EXIT'",v->{if(v.contains("HANDLED"))return;long now=System.currentTimeMillis();if(now-backTime<2000)finish();else{backTime=now;Toast.makeText(this,"뒤로 한 번 더 누르면 종료합니다",0).show();}});}
static class ModernBack {
@android.annotation.TargetApi(33) static void register(MainActivity activity){activity.getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,activity::handleBack);}
}
@Override protected void onPause(){if(web!=null)web.evaluateJavascript("window.GameAudio && GameAudio.suspend();window.clearEffects && clearEffects();window.finishDialogue && finishDialogue();window.flushPersist && window.flushPersist()",null);super.onPause();}
@Override protected void onResume(){super.onResume();if(web!=null)web.evaluateJavascript("window.GameAudio && GameAudio.resume()",null);}
@Override protected void onDestroy(){if(files!=null)files.onReceiveValue(null);if(web!=null)web.destroy();super.onDestroy();}
}
